local Players = game:GetService("Players") local LocalPlayer = Players.LocalPlayer local RunService = game:GetService("RunService") local Workspace = game:GetService("Workspace") local CoreGui = game:GetService("CoreGui") local TweenService = game:GetService("TweenService") local UserInputService = game:GetService("UserInputService") if _G.NotoSilentAimLoaded then return end _G.NotoSilentAimLoaded = true local saFov = 150 local saShowFov = true local saVisCheck = true local saMethod = "Raycast" local saTarget = nil local saFovFrame = nil local saTargetFrame = nil local saOldNamecall = nil local saRaycastParams = RaycastParams.new() saRaycastParams.FilterType = Enum.RaycastFilterType.Include local function isPlayerModel(m) for _, p in ipairs(Players:GetPlayers()) do if p.Character == m then return true end end return false end local function rawVisibility(part) if not LocalPlayer.Character then return false end local rp = RaycastParams.new() rp.FilterType = Enum.RaycastFilterType.Exclude rp.FilterDescendantsInstances = {LocalPlayer.Character, part.Parent} return not Workspace:Raycast(Workspace.CurrentCamera.CFrame.Position, part.Position - Workspace.CurrentCamera.CFrame.Position, rp) end local function headOfModel(m) return m:FindFirstChild("Head") or m:FindFirstChild("HumanoidRootPart") end local function getSilentAimTarget() local chars = Workspace:FindFirstChild("Characters") if not chars then return nil end local cam = Workspace.CurrentCamera local center = Vector2.new(cam.ViewportSize.X/2, cam.ViewportSize.Y/2) local bestDist = saFov local bestTarget = nil for _, m in ipairs(chars:GetChildren()) do if m.Parent and not isPlayerModel(m) then local hum = m:FindFirstChildOfClass("Humanoid") if hum and hum.Health > 0 then local head = headOfModel(m) if head then local sp, onScreen = cam:WorldToViewportPoint(head.Position) if onScreen then local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude if d < bestDist and (not saVisCheck or rawVisibility(head)) then bestDist = d bestTarget = head end end end end end end return bestTarget end local function setupSilentAimUI() local screenGui = Instance.new("ScreenGui") screenGui.Name = "SACircles" screenGui.Parent = CoreGui screenGui.IgnoreGuiInset = true saFovFrame = Instance.new("Frame") saFovFrame.AnchorPoint = Vector2.new(0.5, 0.5) saFovFrame.BackgroundTransparency = 1 saFovFrame.BorderSizePixel = 0 saFovFrame.Visible = false saFovFrame.Parent = screenGui local fovCorner = Instance.new("UICorner") fovCorner.Parent = saFovFrame local fovStroke = Instance.new("UIStroke") fovStroke.Parent = saFovFrame fovStroke.Color = Color3.fromRGB(255, 0, 0) fovStroke.Thickness = 1 saTargetFrame = Instance.new("Frame") saTargetFrame.AnchorPoint = Vector2.new(0.5, 0.5) saTargetFrame.BackgroundTransparency = 1 saTargetFrame.BorderSizePixel = 0 saTargetFrame.Visible = false saTargetFrame.Parent = screenGui local tarCorner = Instance.new("UICorner") tarCorner.Parent = saTargetFrame local tarStroke = Instance.new("UIStroke") tarStroke.Parent = saTargetFrame tarStroke.Color = Color3.fromRGB(255, 255, 255) tarStroke.Thickness = 1.5 end local function startSilentAim() setupSilentAimUI() task.spawn(function() while true do saTarget = getSilentAimTarget() task.wait(0.03) end end) RunService.RenderStepped:Connect(function() local cam = Workspace.CurrentCamera local center = Vector2.new(cam.ViewportSize.X/2, cam.ViewportSize.Y/2) local fovRadius = saFov if saFovFrame then saFovFrame.Size = UDim2.new(0, fovRadius*2, 0, fovRadius*2) if saFovFrame:FindFirstChild("UICorner") then saFovFrame:FindFirstChild("UICorner").CornerRadius = UDim.new(0, fovRadius) end saFovFrame.Position = UDim2.new(0, center.X, 0, center.Y) saFovFrame.Visible = saShowFov end if saTarget and saTarget.Parent then local pos, onScreen = cam:WorldToViewportPoint(saTarget.Position) if onScreen and saTargetFrame then saTargetFrame.Position = UDim2.new(0, pos.X, 0, pos.Y) saTargetFrame.Size = UDim2.new(0, 12, 0, 12) if saTargetFrame:FindFirstChild("UICorner") then saTargetFrame:FindFirstChild("UICorner").CornerRadius = UDim.new(0, 6) end if saVisCheck then saTargetFrame.Visible = rawVisibility(saTarget) else local vis = rawVisibility(saTarget) saTargetFrame:FindFirstChild("UIStroke").Color = vis and Color3.fromRGB(0,255,0) or Color3.fromRGB(255,0,0) saTargetFrame.Visible = true end else if saTargetFrame then saTargetFrame.Visible = false end end else if saTargetFrame then saTargetFrame.Visible = false end end end) if not saOldNamecall then saOldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...) local method = getnamecallmethod() if saTarget and saTarget.Parent and not checkcaller() then local sm = saMethod if sm == "Raycast" and method == "Raycast" then local args = {...} local origin, dir = args[1], args[2] if typeof(origin) == "Vector3" and typeof(dir) == "Vector3" then args[2] = (saTarget.Position - origin).Unit * math.max(dir.Magnitude, 1000) return saOldNamecall(self, unpack(args, 1, 3)) end elseif sm == "ViewportPointToRay" and (method == "ViewportPointToRay" or method == "ScreenPointToRay") then local dir = (saTarget.Position - Workspace.CurrentCamera.CFrame.Position).Unit return Ray.new(Workspace.CurrentCamera.CFrame.Position, dir * 1000) end end return saOldNamecall(self, ...) end)) end end startSilentAim()
